// 카메라 트랜스폼
const cam=ln.cam||{zs:1,ze:1};
const t=Math.min(1,lineElapsed/(ln.dur||1));
const ef=_ease[cam.ease||'linear']||_ease.linear;
const et=ef(t);
const zoom=cam.zs+(cam.ze-cam.zs)*et;
const panX=(cam.px||0)*et;
const panY=(cam.py||0)*et;
// shake
const vfx=ln.vfx||{};
const sk=_cutShake(vfx.shake||0,now);
cx.translate(cw/2+panX+sk.x,ch/2+panY+sk.y);
cx.scale(zoom,zoom);
cx.translate(-cw/2,-ch/2);
// cover 방식 draw
const imgR=img.naturalWidth/img.naturalHeight;
const cR=cw/ch;
let dw,dh,dx,dy;
if(imgR>cR){dh=ch;dw=ch*imgR;dx=(cw-dw)/2;dy=0}
else{dw=cw;dh=cw/imgR;dx=0;dy=(ch-dh)*.1}
cx.drawImage(img,dx,dy,dw,dh);
